"""Record additive packaging-helper derivations after the timing quiet period; never executes Java."""

import argparse
import difflib
import hashlib
import json
from pathlib import Path


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]
OLD = ROOT / 'result-coordinate-evidence/compact-page-followup/delivery'


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--prior-delivery', type=Path, required=True)
    args = parser.parse_args()
    prior = args.prior_delivery.resolve(strict=True)
    summary_path = prior / 'package-summary.json'
    summary_digest = digest(summary_path)
    assert summary_digest == '89522dc48ea234a8ee7addcdb446fe0f6a11e2e5d046a39f902cceb4059fcec0'
    summary = json.loads(summary_path.read_text())
    assert summary['snapshot_tree'] == '993e4358ab1968e6a329c762c5f5ab2109670eed'
    manifest_path = prior / 'source-manifest.json'
    assert digest(manifest_path) == summary['artifacts']['source-manifest.json']['sha256']
    entries = {entry['path']: entry for entry in json.loads(manifest_path.read_text())['entries']}
    derivations = []
    for old_name, new_name in (
        ('prepare-selection.py', 'prepare-selection.py'),
        ('build-turn-delta.py', 'build-turn-delta.py'),
        ('bundle-compact-runtime.py', 'bundle-publication-runtime.py'),
        ('verify-and-relocate-runtime.py', 'verify-and-relocate-runtime.py'),
        ('runtime_bundle_io.py', 'runtime_bundle_io.py'),
    ):
        before, after = OLD / old_name, HERE / new_name
        old_rel, new_rel = before.relative_to(ROOT).as_posix(), after.relative_to(ROOT).as_posix()
        original_digest = digest(before)
        assert original_digest == entries[old_rel]['sha256'], 'Original helper differs from prior delivered source'
        derivations.append({'preservedOriginal': old_rel, 'preservedOriginalSha256': original_digest,
            'matchesPriorSourceManifest': True,
            'newDerivative': new_rel, 'newDerivativeSha256': digest(after),
            'change': ''.join(difflib.unified_diff(before.read_text().splitlines(True), after.read_text().splitlines(True),
                                                  fromfile='a/' + old_rel, tofile='b/' + new_rel))})
    external_before = prior.parent / 'build-selected-candidate-patch.py'
    external_after = HERE / 'build-selected-overlay-patch.py'
    external_digest = digest(external_before)
    assert external_digest == 'b26284b35266df2d2c6b55df332fac738827dc720416948b89958db837fc763f'
    derivations.append({'preservedOriginal': str(external_before),
        'preservedOriginalSha256': external_digest, 'matchesPriorDeliveredManifestPin': True,
        'newDerivative': external_after.relative_to(ROOT).as_posix(), 'newDerivativeSha256': digest(external_after),
        'change': ''.join(difflib.unified_diff(external_before.read_text().splitlines(True),
            external_after.read_text().splitlines(True), fromfile='a/' + external_before.name,
            tofile='b/' + external_after.relative_to(ROOT).as_posix()))})
    catalog = HERE / 'runtime_bundle_io.py'
    io = ROOT / 'result-coordinate-evidence/materializer-followup/comparison_runtime_io.py'
    io_relative = io.relative_to(ROOT).as_posix()
    assert digest(io) == entries[io_relative]['sha256'], 'Shared runtime inventory helper changed'
    packager = ROOT / 'result-coordinate-evidence/package-coordinate-deliverables.py'
    packager_relative = packager.relative_to(ROOT).as_posix()
    assert digest(packager) == entries[packager_relative]['sha256'], 'Complete-source packager changed'
    previous_selection = OLD / 'selection.json'
    previous_relative = previous_selection.relative_to(ROOT).as_posix()
    previous_digest = digest(previous_selection)
    assert previous_digest == entries[previous_relative]['sha256'], 'Prior source selection changed'
    prepared = HERE / 'packaging-v1-pre-incomplete'
    prepared_receipt = prepared / 'preservation.json'
    prepared_record = json.loads(prepared_receipt.read_text())
    assert prepared_record['packagingPreviouslyExecuted'] is False and len(prepared_record['files']) == 8
    stopped_adaptations = []
    for filename, original in sorted(prepared_record['files'].items()):
        before, after = prepared / filename, HERE / filename
        assert before.stat().st_size == original['bytes'] and digest(before) == original['sha256'], \
            'Prepared complete-study helper snapshot changed'
        stopped_adaptations.append({'preservedPreparedFile': before.relative_to(ROOT).as_posix(),
            'preservedSha256': original['sha256'], 'activeFile': after.relative_to(ROOT).as_posix(),
            'activeSha256': digest(after),
            'change': ''.join(difflib.unified_diff(before.read_text().splitlines(True), after.read_text().splitlines(True),
                fromfile='a/' + before.relative_to(ROOT).as_posix(), tofile='b/' + after.relative_to(ROOT).as_posix()))})
    record = {'format': 1, 'priorSourceTree': '993e4358ab1968e6a329c762c5f5ab2109670eed',
              'priorPackageSummarySha256': summary_digest,
              'priorSourceManifestSha256': digest(manifest_path),
              'previousSelection': previous_relative, 'previousSelectionSha256': previous_digest,
              'derivations': derivations,
              'newRuntimeCatalog': {'path': catalog.relative_to(ROOT).as_posix(), 'sha256': digest(catalog)},
              'sharedVerifiedIo': {'path': io_relative, 'sha256': digest(io), 'matchesPriorSourceManifest': True},
              'unchangedCompleteSourcePackager': {'path': packager_relative, 'sha256': digest(packager),
                                                'matchesPriorSourceManifest': True},
              'stoppedStudyAdaptation': {'preservationRecord': prepared_receipt.relative_to(ROOT).as_posix(),
                  'preservationRecordSha256': digest(prepared_receipt), 'reason': prepared_record['reason'],
                  'preparedVersionsNeverExecuted': True, 'changes': stopped_adaptations},
              'originalHelpersMatchPriorDeliveredSource': True, 'javaExecuted': False}
    target = HERE / 'delta-helper-derivation.json'
    with target.open('x') as stream:
        json.dump(record, stream, indent=2, sort_keys=True)
        stream.write('\n')
    print(target)


if __name__ == '__main__':
    main()
